import {countries,domains,roles,missions,countryName,crewTypes,DEFAULT_PLACE} from './content.js';
import {locales,localeCode,t,localized,loadLocaleExtras,loadCrewText,crewText,pickLocale,EXTRA} from './i18n.js';
import {CREW_ICONS,crewIcon,crewColor,satTiles} from './crew-icons.js';
import {photos,mediaItems,maritimeMedia,mapCredit} from './media.js';
import {createServices} from './services.js';
import {createTutor,DEFAULT_MODEL_URL,MODEL_INFO,coachModelURL} from './tutor.js';
const $=(q,el=document)=>el.querySelector(q), $$=(q,el=document)=>[...el.querySelectorAll(q)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cached=(key,fallback)=>{try{return localStorage.getItem(key)||fallback}catch{return fallback}};
let lang=pickLocale(cached('crew-language',''));await Promise.all([loadLocaleExtras(lang),loadCrewText(lang)]);
const SPEECH={"fil": "fil-PH", "km": "km-KH", "my": "my-MM", "bn": "bn-BD", "mr": "mr-IN", "ta": "ta-IN", "te": "te-IN", "ur": "ur-PK", "fa": "fa-IR", "he": "he-IL", "tr": "tr-TR", "ru": "ru-RU", "uk": "uk-UA", "pl": "pl-PL", "cs": "cs-CZ", "ro": "ro-RO", "hu": "hu-HU", "el": "el-GR", "nl": "nl-NL", "da": "da-DK", "sv": "sv-SE", "nb": "nb-NO", "fi": "fi-FI", "sw": "sw-KE"};
const T=k=>t(lang,k), C=(k,v)=>crewText(k,v), L=v=>v&&v.k?crewText(v.k):localized(v,lang), safeText=v=>esc(L(v));
const icons={home:'M3 10 12 3l9 7M5 9v11h5v-6h4v6h5V9',missions:'M8 4H5v17h14V4h-3M8 3h8v4H8zM8 11h8M8 15h5',map:'m3 5 6-2 6 2 6-2v16l-6 2-6-2-6 2zM9 3v16M15 5v16',crew:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M17 4a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.9M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',academy:'m2 8 10-5 10 5-10 5zM5 10v7c4 4 10 4 14 0v-7M22 8v8',showcase:'m12 3 9 5-9 5-9-5zM3 12l9 5 9-5M3 16l9 5 9-5',profile:'M20 21v-2a7 7 0 0 0-14 0v2M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',air:'m3 11 7 1 2 9 2-9 7-1-7-3-2-6-2 6z',land:'m4 7 2-3h12l2 3 1 5v6h-3v-3H6v3H3v-6zM4 9h16M6 12h2M16 12h2',sea:'M12 3v12M7 8h10v7l4 3c-3 5-6 1-9 2-3-1-6 3-9-2l4-3z',digital:'M3 4h18v13H3zM8 21h8M12 17v4M7 8l-2 2 2 2M16 8l2 2-2 2',play:'m9 4 12 8-12 8z',arrow:'M4 12h16M14 6l6 6-6 6',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3c5 5 5 13 0 18-5-5-5-13 0-18',check:'m4 12 5 5L20 6',shield:'m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6zM8 12l3 3 5-6',close:'m5 5 14 14M19 5 5 19',menu:'M3 6h18M3 12h18M3 18h18',coach:'M4 5h16v12H9l-5 4zM8 9h8M8 13h5',download:'M12 3v12M7 10l5 5 5-5M4 17v4h16v-4',time:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 6v6l4 2',photo:'M3 7h5l2-3h4l2 3h5v14H3zM16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0'};
icons.under='M3 15c2 1.5 4 1.5 6 0s4-1.5 6 0 4 1.5 6 0M12 3v8M8 7l4 4 4-4M3 20h18';icons.fly='M2 13l9-2 3-8h2l-1 8 6 1v2l-6 1 1 6h-2l-3-6-9-2z';
const icon=name=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${icons[name]||icons.showcase}" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
const btn=(label,action,cls='',ic='')=>`<button class="${cls} ${ic?'btn-icon':''}" data-action="${action}">${ic?icon(ic):''}${esc(T(label))}</button>`;
const link=(url,label,cls='text-link')=>`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`;
let svc;try{svc=createServices(window.CREW_CONFIG||{})}catch(e){svc=createServices({});console.error(e.code)}
let region='all',mtype='all',simFrame=null,simResult=null,pendingSim=false;
let page='home',mission=missions[0],selectedCountry='TW',filter='all',level='all',query='',trainer=null,sceneGeneration=0,telemetry=null,logs=[],checks=new Set(),digitalStep=0,room=null,members=[],user=null,role=['pilot','navigator','observer','coordinator'].includes(cached('crew-role',''))?cached('crew-role',''):'pilot',remoteState=null,selectedVideo=mediaItems[0],videoURL=null,mapData=null,coords=null,activeEmbedded=null,lastPublish=0;
const keys=new Set(),touchInputs=new Map();
let assistance=true,camera='chase',weather='clear',difficulty='basic';
let mentorUI=null,mediaUI=null,plannerUI=null,coachContext=null;
let theme=['light','dark','system'].includes(cached('crew-theme','system'))?cached('crew-theme','system'):'system';
let density=cached('crew-density','comfortable')==='compact'?'compact':'comfortable';
function applyPreferences(){document.documentElement.dataset.theme=theme==='system'?(window.matchMedia?.('(prefers-color-scheme: dark)').matches?'dark':'light'):theme;document.documentElement.dataset.density=density;}
window.matchMedia?.('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if(theme==='system')applyPreferences()});
applyPreferences();
const cname=id=>countryName?countryName(id,lang):new Intl.DisplayNames([lang],{type:'region'}).of(id);
const mapISO=f=>({TWN:'TW',FRA:'FR',NOR:'NO'}[f.properties.iso_a3]||f.properties.iso_a2);
const photoFor=d=>photos.find(x=>x.id===({air:'cockpit-crew',land:'firetruck-training',sea:'bridge-crew',digital:'groundcontrol-crew'}[d]))||photos[0];
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('visible'),4500)}
function failure(e){toast(`${T('error')}: ${e?.code||e?.message||T('networkError')}`)}
function addLog(type,detail=''){logs.unshift({at:new Date().toISOString(),type,detail});logs=logs.slice(0,150);renderLogs()}
function renderLogs(){const el=$('#event-log');if(el)el.innerHTML=logs.slice(0,20).map(e=>`<div>${esc(new Date(e.at).toLocaleTimeString(lang))} · ${esc(e.type)} ${esc(e.detail)}</div>`).join('')}
function cleanup(){sceneGeneration++;for(const module of [mentorUI,mediaUI,plannerUI])module?.destroy();mentorUI=mediaUI=plannerUI=null;if(trainer){trainer.destroy();trainer=null}keys.clear();touchInputs.clear();if(videoURL){URL.revokeObjectURL(videoURL);videoURL=null}activeEmbedded=null}
function go(to){cleanup();page=to;render();window.scrollTo({top:0,behavior:'instant'})}
function render(){document.documentElement.lang=lang;document.documentElement.dir=locales.find(x=>x.code===lang)?.dir||'ltr';document.title=`RESILIENCE · ${T(page==='training'?'practice':page)}`;
const navs=['home','missions','planner','map','crew','academy','aero','showcase'];
$('#app').innerHTML=`<div class="menu-overlay" data-action="menu"></div><aside class="sidebar"><a class="brand" href="#home" data-nav="home"><img src="icon.svg" alt=""><span>RESILIENCE<small>CREW LAB / 03</small></span></a><div class="eyebrow nav-label">${esc(T('home'))}</div><nav class="nav" aria-label="${esc(T('home'))}">${navs.map((n,i)=>`<button data-nav="${n}" class="${page===n?'active':''}">${icon(n==='aero'?'air':n)}<span>${n==='aero'?'AERO Explorer':esc(T(n))}</span>${n==='missions'?`<small style="margin-left:auto">${missions.length}</small>`:''}</button>`).join('')}</nav><div class="sidebar-foot"><nav class="nav"><button data-nav="settings">${icon('settings')}${esc(T('settings'))}</button><button data-action="coach">${icon('coach')}${esc(T('coach'))}</button></nav><hr><small><span class="status-dot"></span>${esc(T(svc.channelMode==='cloud'?'cloudSession':'localSession'))}</small><div class="eyebrow" style="margin-top:6px">${esc(T('publicData'))}</div></div></aside><div class="main"><header class="topbar"><div class="topbar-left">${btn('home','menu','mobile-toggle','menu')}<span class="eyebrow">CREW LAB <span style="color:#a8b8a4;margin:0 10px">/</span> ${esc(T(page==='training'?'practice':page==='aero'?'practice':page))}</span></div><div class="topbar-actions"><label class="sr-only" for="locale">${esc(T('language'))}</label><select id="locale">${locales.map(l=>`<option value="${l.code}" ${l.code===lang?'selected':''}>${l.label}</option>`).join('')}</select><button class="ghost btn-icon" data-nav="profile">${icon('profile')}<span class="account-label">${esc(T(user?'profile':'guest'))}</span></button></div></header><main class="content" id="main-content">${pages[page]()}</main><footer class="footer"><span>© 2026 RESILIENCE CREW LAB · ${esc(T('publicData'))}</span><span>${esc(T('noLiveData'))} · <button class="text-link" data-nav="settings">${esc(T('sources'))} ↗</button></span></footer></div>`;
if(page==='map'||page==='home')drawMap();if(page==='training')initTraining();if(page==='crew')renderRoom();if(['academy','training','planner'].includes(page))mountEnhancement();if(page==='profile'&&user)loadProfile();renderLogs();}
function heading(key,sub='',action=''){return `<div class="breadcrumbs">RESILIENCE / ${esc(T(key))}</div><div class="page-heading"><div><div class="eyebrow">CREW LAB · ${esc(T('publicData'))}</div><h1>${esc(T(key))}</h1></div>${action}</div>`}
function missionCard(m){const p=m.place;return `<article class="card crew-card">${cardArt(m)}<div class="card-body"><div class="tags"><span class="tag ${m.domain}">${icon(m.domain)}${esc(dname(m.domain))}</span><span class="tag">${esc(T(m.level))}</span>${m.vehicle?`<span class="tag">${esc(C('crew.veh.'+m.vehicle))}</span>`:''}<span class="tag">${m.durationMinutes} ${esc(T('minutes'))}</span></div><h3>${safeText(m.title)}</h3>${p?`<p class="crew-place">${icon('map')}<span>${esc(placeLabel(p))}${placeWhere(p)?' · '+esc(placeWhere(p)):''}</span></p>`:''}<p class="crew-brief">${safeText(m.description)}</p><div class="actions"><button class="text-link" data-mission="${m.id}">${esc(T('briefing'))} ${icon('arrow')}</button><small style="margin-left:auto">${m.id.toUpperCase()}</small></div></div></article>`}
function home(){return `${heading('home','A SHARED SPACE FOR EVERY CREW')}<section class="hero"><div class="hero-copy"><div class="eyebrow">RESILIENCE / CROSS-DOMAIN TRAINING</div><h1>${esc(T('tagline'))}</h1><p>${esc(C('crew.homeIntro',{n:missions.length}))}</p><div class="actions"><button class="primary btn-icon" data-action="fly-now">${icon('fly')}${esc(C('crew.flyNow'))}</button><button class="soft btn-icon" data-nav="missions">${esc(T('selectMission'))}${icon('arrow')}</button><button data-nav="planner" class="soft btn-icon">${icon('map')}${esc(T('planner'))}</button></div><small style="margin-top:22px">${esc(C('crew.simIntro'))}</small></div><div class="hero-visual"><img src="assets/taiwan-coast.webp" alt="${esc(L(photos[0].title))}"><div class="hero-lines"></div><div class="hero-caption"><span class="tag">23.99° N · 121.65° E</span><h3 style="margin:10px 0 3px">${esc(L(photos[0].title))}</h3><small>Zairon · CC BY-SA 4.0 · ${link(photos[0].sourceUrl,T('openOriginal'))}</small></div></div></section><div class="stats">${[[missions.length,T('missionCount'),'missions'],[Object.keys(crewTypes).length,C('crew.types'),'showcase'],[locales.length,T('language'),'globe'],[2776,C('crew.destinations'),'map']].map(([n,label,i])=>`<div class="stat">${icon(i)}<div><strong>${n.toLocaleString(lang)}</strong><span>${esc(label)}</span></div></div>`).join('')}</div><div class="section-head"><h2>${esc(T('missions'))}</h2><button class="text-link" data-nav="missions">${esc(T('all'))} ${icon('arrow')}</button></div><div class="cards">${[missions.find(m=>m.domain==='air'&&m.place?.cc==='TW'),missions.find(m=>m.domain==='sea'&&m.place?.cc==='TW'),missions.find(m=>m.domain==='under')].filter(Boolean).map(missionCard).join('')}</div><div class="two-col"><section class="panel"><div class="section-head" style="margin-top:0"><h2>${esc(T('map'))}</h2><button class="text-link" data-nav="map">${esc(T('openMap'))} ↗</button></div><div class="map-box" id="world-map"></div><div class="country-summary"><div><div class="eyebrow">${esc(T('country'))}</div><h3 style="margin:6px 0">${esc(cname('TW'))}</h3><small>${esc(T('countryNotice'))}</small></div><span class="flag">🇹🇼</span></div></section><section class="panel event-panel"><div class="eyebrow">FIELD NOTES / 20 OCT 2026</div><h2 style="margin-top:15px">${esc(T('eventTitle'))}</h2><p>${esc(T('eventPurpose'))}</p><div class="schedule"><div><b>140</b><span>${esc(T('eventPeople'))}</span></div><div><b>14:00</b><span>${esc(T('start'))}</span></div><div><b>17:00</b><span>${esc(T('debrief'))}</span></div></div><p>${esc(T('eventLocation'))}</p><small style="color:#b9ccb4">${esc(T('eventNotice'))}</small><div style="margin-top:22px"><button class="soft" data-nav="crew">${esc(T('createRoom'))} ↗</button></div></section></div>`}
function missionLibrary(){const types=Object.entries(crewTypes);return `${heading('missions')}<p class="crew-lead">${esc(C('crew.libraryHead',{n:missions.length,t:types.length}))}</p><div class="filters crew-filters"><input id="mission-search" placeholder="${esc(C('crew.search'))}" aria-label="${esc(C('crew.search'))}" value="${esc(query)}"><select id="domain-filter" aria-label="${esc(T('terrain'))}">${['all','air','land','sea','under','digital'].map(d=>`<option value="${d}" ${filter===d?'selected':''}>${esc(d==='all'?C('crew.allDomains'):dname(d))}</option>`).join('')}</select><select id="level-filter" aria-label="${esc(T('difficulty'))}">${['all','basic','advanced','expert'].map(d=>`<option value="${d}" ${level===d?'selected':''}>${esc(d==='all'?C('crew.allLevels'):T(d))}</option>`).join('')}</select><select id="region-filter" aria-label="${esc(T('country'))}">${['all','tw','world'].map(d=>`<option value="${d}" ${region===d?'selected':''}>${esc(d==='all'?C('crew.allRegions'):C('crew.region.'+d))}</option>`).join('')}</select><select id="type-filter" aria-label="${esc(C('crew.typeFilter'))}"><option value="all">${esc(C('crew.allTypes'))}</option>${types.map(([id,x])=>`<option value="${id}" ${mtype===id?'selected':''}>${esc(dname(x.domain))} · ${esc(C('crew.type.'+id+'.title'))}</option>`).join('')}</select></div><p class="crew-count" id="mission-count" aria-live="polite"></p><div class="cards" id="mission-cards">${filteredCards()}</div><div class="notice">${esc(C('crew.fictional'))} ${esc(C('crew.imagery'))}</div>`}
function filteredCards(){const q=query.trim().toLowerCase();const list=missions.filter(m=>(filter==='all'||m.domain===filter)&&(level==='all'||m.level===level)&&(region==='all'||(region==='tw'?m.place?.cc==='TW':!!m.place&&m.place.cc!=='TW'))&&(mtype==='all'||m.type===mtype)&&(!q||`${L(m.title)} ${L(m.description)} ${m.place?`${m.place.zh} ${m.place.en} ${m.place.zhs} ${m.place.region}`:''} ${m.id}`.toLowerCase().includes(q)));const n=C('crew.count',{n:list.length});setTimeout(()=>{const e=$('#mission-count');if(e)e.textContent=n});return list.length?list.map(missionCard).join(''):`<p>${esc(T('noResults'))}</p>`}
function countrySelect(){return `<select id="country-select" aria-label="${esc(T('selectCountry'))}">${countries.map(c=>`<option value="${esc(c.id)}" ${c.id===selectedCountry?'selected':''}>${esc(cname(c.id))}</option>`).join('')}</select>`}
function mapPage(){return `${heading('map','PUBLIC GEOGRAPHY · NO OPERATIONAL DATA')}<div class="world-layout"><section class="panel"><div class="actions" style="margin-bottom:18px">${countrySelect()}${btn('locateMe','locate','','map')}</div><div class="map-box" id="world-map"></div><div class="country-summary"><div><h2 id="country-name">${esc(cname(selectedCountry))}</h2><small id="coordinate">${coords?`${coords.lat.toFixed(5)}, ${coords.lon.toFixed(5)}`:T('noLiveData')}</small></div><a id="google-map" class="primary" style="padding:9px 14px;border-radius:8px" href="https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(cname(selectedCountry))}" target="_blank" rel="noopener noreferrer">${esc(T('openMap'))} ↗</a></div><div class="notice">${esc(T('countryNotice'))}</div><small>Natural Earth · Public domain · 177 polygons · ${link(mapCredit.sourceUrl,T('sources'))}</small></section><section class="panel"><h2>${esc(T('practice'))}</h2><p>${esc(T('mapPracticeNotice'))}</p>${['air','land','sea','under','digital'].map((d,i)=>`<div class="list-row">${icon(d)}<div><strong>${esc(dname(d))}</strong><p>${missions.filter(m=>m.domain===d).length} ${esc(T('missionCount'))}</p></div><button class="text-link end" data-filter="${d}">${icon('arrow')}<span class="sr-only">${esc(T('selectMission'))}</span></button></div>`).join('')}<hr><img src="assets/taiwan-coast.webp" style="width:100%;border-radius:8px" alt="${esc(L(photos[0].title))}"><small>${esc(L(photos[0].title))} · Zairon / CC BY-SA 4.0</small></section></div>`}
async function drawMap(){const target=$('#world-map');if(!target)return;try{if(!mapData)mapData=await fetch('assets/world-countries.geojson').then(r=>{if(!r.ok)throw Error('map');return r.json()});if(!target.isConnected)return;const path=geom=>{const rings=geom.type==='Polygon'?[geom.coordinates]:geom.coordinates;return rings.map(p=>p.map(r=>r.map(([lon,lat],i)=>`${i?'L':'M'}${((lon+180)*2).toFixed(1)},${((90-lat)*2).toFixed(1)}`).join(' ')+'Z').join(' ')).join(' ')};target.innerHTML=`<svg viewBox="0 0 720 360" role="img" aria-label="${esc(T('map'))}">${mapData.features.map(f=>`<path data-country="${esc(mapISO(f))}" d="${path(f.geometry)}" class="${mapISO(f)===selectedCountry?'selected':''}"><title>${esc(f.properties.name)}</title></path>`).join('')}<circle class="map-point" cx="602" cy="133" r="4"/>${coords?`<circle class="map-point" cx="${(coords.lon+180)*2}" cy="${(90-coords.lat)*2}" r="4"/>`:''}</svg>`}catch(e){target.textContent=T('networkError')}}
function trainingPage(){const m=mission,p=m.place,dig=m.domain==='digital';return `${heading('practice',m.id.toUpperCase(),btn('coach','coach','soft','coach'))}<div class="page-heading"><div><div class="tags"><span class="tag ${m.domain}">${icon(m.domain)}${esc(dname(m.domain))}</span><span class="tag">${esc(T(m.level))}</span>${m.vehicle?`<span class="tag">${esc(C('crew.veh.'+m.vehicle))}</span>`:''}${p?`<span class="tag">${esc(placeLabel(p))}${placeWhere(p)?' · '+esc(placeWhere(p)):''}</span>`:''}</div><h2 style="margin:0">${safeText(m.title)}</h2></div><button data-nav="missions" class="text-link">${esc(T('selectMission'))} ↗</button></div>${dig?`<section id="mentor-root" class="module-root" aria-label="${esc(T('guide'))}"></section>`:''}<div class="trainer-layout"><div class="trainer-area">${dig?digitalDesk():simLauncher()}<section class="panel"><div class="section-head" style="margin:0 0 15px"><h3>${esc(T('objectives'))}</h3>${btn('export','export','','download')}</div><ol>${m.objectives.map(o=>`<li>${safeText(o)}</li>`).join('')}</ol><p class="crew-tip"><b>${esc(C('crew.tip'))}:</b> ${safeText(m.briefing[0])}</p><small>${esc(T('sources'))}: ${m.sourceUrls.map(url=>link(url,new URL(url).hostname)).join(' · ')}</small></section></div><aside class="training-side"><section class="panel"><h3>${esc(T('briefing'))}</h3><p>${safeText(m.description)}</p><h3>${esc(T('checklist'))}</h3><ul class="crew-checks">${m.checklist.map(c=>`<li>${safeText(c)}</li>`).join('')}</ul><p class="crew-roletip"><b>${esc(C('crew.role'))}:</b> ${esc(C('crew.roleTip.'+role))}</p><div class="notice">${esc(C('crew.fictional'))}</div></section><section class="panel"><h3>${esc(T('record'))}</h3><div class="timeline" id="event-log"></div></section></aside></div>`}
function digitalDesk(){const st=mission.deskSteps;return `<div class="digital-desk">${cardArt(mission,'big')}<div class="eyebrow" style="color:#bdd5be;margin-top:14px">${esc(T('digitalDesk'))} · ${esc(C('crew.digitalSteps'))}</div><h2 style="margin-top:10px">${safeText(mission.title)}</h2><p>${safeText(mission.description)}</p><p style="opacity:.85">${esc(C('crew.digitalNote'))}</p>${st.map((c,i)=>`<div class="digital-step ${i<digitalStep?'complete':''}"><b>${String(i+1).padStart(2,'0')}</b><span>${safeText(c)}</span><button data-digital="${i}" ${i!==digitalStep?'disabled':''}>${i<digitalStep?'✓':esc(C('crew.markDone'))}</button></div>`).join('')}<strong>${esc(T('score'))}: ${Math.round(digitalStep/st.length*100)} / 100</strong><div class="actions" style="margin-top:20px">${btn('reset','reset')}${btn('export','export','','download')}<button class="soft" data-action="next-mission">${esc(C('crew.nextMission'))}</button></div></div>`}
function initTraining(){telemetry=null;if(mission.domain==='digital')return;if(pendingSim){pendingSim=false;openSim()}}
function updateTelemetry(d){telemetry=d;for(const [key,value]of Object.entries({progress:`${d.progress??0}/${d.total??0}`,speed:(+d.speed||0).toFixed(1),altitude:Math.round(+d.altitude||0),battery:`${Math.round(+d.battery||0)}%`,score:Math.round(+d.score||0)})){const el=$(`#tm-${key}`);if(el)el.textContent=value}if(room&&svc.isHost&&Date.now()-lastPublish>2000){lastPublish=Date.now();svc.publishState({missionId:d.missionId||mission.id,role,country:selectedCountry,telemetry:d,checkCount:3}).catch(failure)}}
function input(){const x={forward:0,turn:0,strafe:0,lift:0};if(keys.has('w')||keys.has('arrowup'))x.forward++;if(keys.has('s')||keys.has('arrowdown'))x.forward--;if(keys.has('a')||keys.has('arrowleft'))x.turn--;if(keys.has('d')||keys.has('arrowright'))x.turn++;if(keys.has('q'))x.strafe--;if(keys.has('e'))x.strafe++;if(keys.has('r'))x.lift++;if(keys.has('f'))x.lift--;for(const v of touchInputs.values())x[v.axis]+=v.value;trainer?.setInput(x)}
function crewPage(){return `${heading('crew','FOUR ROLES · ONE SHARED PICTURE')}<div class="notice">${esc(T('roomNotice'))}</div><section class="panel"><div class="actions">${btn('createRoom','create-room','primary','crew')}<input id="room-code-input" placeholder="${esc(T('roomCode'))}" aria-label="${esc(T('roomCode'))}" autocapitalize="characters" maxlength="20">${btn('joinRoom','join-room')}${btn('leaveRoom','leave-room','ghost')}</div><div id="room-status" style="margin-top:15px"></div></section><div class="crew-grid">${['pilot','navigator','observer','coordinator'].map((r,i)=>`<section class="role-card"><div class="avatar">${icon(['air','map','shield','crew'][i])}</div><h3>${esc(T(r))}</h3><p class="small">${esc(T(`role${i+1}`))}</p><button data-role="${r}" class="${r===role?'primary':''}">${r===role?'✓ ':''}${esc(T('confirm'))}</button></section>`).join('')}</div><div class="two-col"><section class="panel"><h2>${esc(T('sharedDisplay'))}</h2><div id="shared-state"><p>${esc(T('statusReady'))}</p></div><div class="actions">${btn('practice','practice','primary','play')}${btn('acknowledge','acknowledge','soft')}${btn('pause','crew-pause')}${btn('confirm','crew-confirm')}</div></section><section class="panel"><h2>${esc(T('message'))}</h2><form id="crew-message-form" class="actions"><input id="crew-message" style="flex:1" maxlength="240" aria-label="${esc(T('message'))}" placeholder="${esc(T('message'))}"><button type="submit" class="primary">${esc(T('send'))}</button></form><div class="timeline" id="event-log" style="max-height:230px"></div>${btn('export','export','text-link','download')}</section></div>`}
function renderRoom(){const el=$('#room-status');if(el)el.innerHTML=room?`<span class="tag">${esc(T(svc.channelMode==='cloud'?'cloudSession':'localSession'))}</span> <span class="code">${esc(T('roomCode'))}: <b>${esc(room.code)}</b></span> · ${members.length} ${esc(T('member'))} · ${esc(T(svc.isHost?'host':'member'))}`:`<span class="small">${esc(T('statusReady'))} · ${esc(T(svc.channelMode==='cloud'?'cloudSession':'localSession'))}</span>`;const shared=$('#shared-state');if(shared&&!remoteState)shared.innerHTML=`<p>${esc(T('statusReady'))}</p>`;if(shared&&remoteState){const m=missions.find(m=>m.id===remoteState.missionId);shared.innerHTML=`<h3>${m?safeText(m.title):esc(T('practice'))}</h3><p>${esc(T('progress'))}: ${remoteState.telemetry?.progress??0}/5 · ${esc(T('score'))}: ${Math.round(remoteState.telemetry?.score??0)}</p><div class="meter"><i style="width:${Math.min(100,(remoteState.telemetry?.progress||0)*20)}%"></i></div><small>${esc(T('stateNotice'))}</small>`}}
function academyPage(){return `${heading('academy')}<div id="media-root" class="module-root"><p>${esc(T('loading'))}</p></div><div class="notice">${esc(T('videoNotice'))}</div>`}
function plannerPage(){return `${heading('planner')}<div id="planner-root" class="module-root"><p>${esc(T('loading'))}</p></div>`}
async function mountEnhancement(){
 const stamp=sceneGeneration,currentPage=page;
 try{
  if(currentPage==='academy'){
   const mediaMod=await import('./media-workspace.js'),{mountMediaWorkspace}=mediaMod;registerExtras('media',mediaMod);if(stamp!==sceneGeneration||page!==currentPage)return;
   mediaUI=mountMediaWorkspace($('#media-root'),{locale:lang,translate:T,mediaItems:[...mediaItems,maritimeMedia],onQuestion:q=>openContextCoach(q),onEvent:e=>addLog(T('record'),JSON.stringify(e))});
  }else if(currentPage==='planner'){
   const plannerMod=await import('./scenario-planner.js'),{mountPlanner}=plannerMod;registerExtras('planner',plannerMod);if(stamp!==sceneGeneration||page!==currentPage)return;
   plannerUI=mountPlanner($('#planner-root'),{locale:lang,translate:T,onEvent:e=>addLog(T('record'),JSON.stringify(e)),onQuestion:q=>openContextCoach(q)});
  }else if(currentPage==='training'&&mission.domain==='digital'){
   const mentorMod=await import('./mentor.js'),{mountMentor}=mentorMod;registerExtras('mentor',mentorMod);if(stamp!==sceneGeneration||page!==currentPage)return;
   mentorUI=mountMentor($('#mentor-root'),{locale:lang,domain:mission.domain,missionTitle:L(mission.title),translate:T,targets:{briefing:'.training-side',checklist:'[data-check]',move:'[data-pad="forward"]',turn:'[data-pad="turn"]',lift:'[data-pad="lift"]',assist:'[data-action="assistance"]',inspect:'[data-action="inspect"]',report:'[data-action="export"]'},onAction:action=>{if(action==='assist'){assistance=true;trainer?.setAssistance(true);$('[data-action="assistance"]')?.classList.add('soft')}else doAction(action).catch(failure)}});
  }
 }catch(e){if(stamp!==sceneGeneration)return;const target=$('#media-root')||$('#planner-root')||$('#mentor-root');if(target)target.textContent=`${T('error')}: ${e.message}`;failure(e)}
}
function openContextCoach(payload){
 const data=typeof payload==='string'?{question:payload}:payload||{};
 coachContext=JSON.stringify({scope:T('contextNotice'),...data}).slice(0,3800);
 openCoach();const field=$('#coach-question');if(field)field.value=String(data.question||data.text||T('askCoach')).slice(0,900);
}
