function embedPage(isAero=false){const list=isAero?[['aero','AERO Explorer','https://kuonanhong.github.io/AERO_Explorer/']]:[['museum','HoloArtisan Portrait Museum','https://kuonanhong.github.io/HoloArtisan_PortraitMuseum/'],['holo','HoloArtisan Demo','https://kuonanhong.github.io/HoloArtisanDemo/']];return `${heading(isAero?'practice':'showcase',isAero?'AERO EXPLORER / LINKED EXPERIENCE':'HOLOARTISAN / IMMERSIVE EXPERIENCE')}<div class="actions" style="margin-bottom:20px">${list.map(([id,title,url])=>`<button data-embed="${id}" class="soft">${esc(title)} ↗</button>${link(url,T('openExternal'))}`).join('')}${isAero?'<button data-embed="aero-local">AERO · Local</button>':''}</div><div class="embed-shell" id="embed-shell"><div class="embed-placeholder">${icon(isAero?'air':'showcase')}<h2>${list[0][1]}</h2><p>${esc(T('mediaConsent'))}</p><button class="primary" data-embed="${list[0][0]}">${esc(T('loadMedia'))}</button></div></div><div class="notice">${esc(T('embedNotice'))}</div>`}
