function profilePage(){return `${heading('profile','ACCOUNT & PRIVACY')}<div class="account-wrap"><section class="panel"><h2>${esc(T('signIn'))}</h2><div class="notice">${esc(T(svc.channelMode==='cloud'?'privacyNotice':'cloudNotConfigured'))}</div>${user?`<p>${esc(user.email||'')}</p>${btn('signOut','signout')}`:`<label for="auth-email">${esc(T('email'))}</label><div class="auth-steps"><input id="auth-email" type="email" autocomplete="email" placeholder="name@example.com">${btn('sendCode','send-code','primary')}</div><label for="auth-code" style="margin-top:20px">${esc(T('verificationCode'))}</label><div class="auth-steps"><input id="auth-code" inputmode="numeric" autocomplete="one-time-code" maxlength="10">${btn('verifyCode','verify-code')}</div>`}</section><section class="panel" style="margin-top:20px"><h2>${esc(T('profile'))}</h2><div class="form-grid"><div class="form-field"><label for="profile-name">${esc(T('name'))}</label><input id="profile-name" autocomplete="name" maxlength="80"></div><div class="form-field"><label for="profile-phone">${esc(T('phone'))} · ${esc(T('optional'))}</label><input id="profile-phone" type="tel" autocomplete="tel" maxlength="32"></div></div><div class="actions" style="margin-top:18px">${btn('save','save-profile','primary')}${btn('guestMode','guest','soft')}</div><p class="hint" style="margin:15px 0 0">${esc(T('profileNotice'))}</p></section></div>`}
function settingsPage(){return `${heading('settings','TRANSPARENCY & SOURCES')}${appearancePanel()}<div class="two-col" style="margin-top:0"><section class="panel"><h2>${esc(T('device'))}</h2><p>${esc(T('deviceNotice'))}</p><div class="list-row"><span>WebGL 2</span><b class="end">${supportsWebGL()?'✓':'—'}</b></div><div class="list-row"><span>WebAssembly</span><b class="end">${typeof WebAssembly!=='undefined'?'✓':'—'}</b></div><div class="list-row"><span>CPU · ${esc(T('device'))}</span><b class="end">${navigator.hardwareConcurrency||'—'}</b></div><div class="list-row"><span>RAM · ${esc(T('device'))}</span><b class="end">${navigator.deviceMemory?`${navigator.deviceMemory} GB`:'—'}</b></div><div class="list-row"><span>${esc(T('channel'))}</span><b class="end">${esc(T(svc.channelMode==='cloud'?'cloudSession':'localSession'))}</b></div></section><section class="panel"><h2>${esc(T('privacy'))}</h2><p>${esc(T('privacyNotice'))}</p><p>${esc(T('aiNotice'))}</p><p>${esc(T('countryNotice'))}</p>${btn('coach','coach','soft','coach')}</section></div><section class="panel" style="margin-top:22px"><h2>${esc(T('sources'))} · ${esc(C('crew.realPlace'))}</h2>${[['Esri World Imagery','© Esri, Maxar, Earthstar Geographics','https://www.arcgis.com/home/item.html?id=10df2279f9684e4a9f6a7f08febac2a9'],['AWS Terrain Tiles (Terrarium)','SRTM, GMTED, ETOPO1 …','https://registry.opendata.aws/terrain-tiles/'],['OpenStreetMap · OpenFreeMap','© OpenStreetMap contributors · ODbL','https://www.openstreetmap.org/copyright'],['Open-Meteo','Weather & marine data · CC BY 4.0','https://open-meteo.com/'],['Wikimedia Commons · Wikipedia','CC BY-SA and file licences','https://commons.wikimedia.org/'],['交通部觀光署 Taiwan Tourism Administration','Open Government Data License','https://data.gov.tw/'],['UNESCO World Heritage','whc.unesco.org','https://whc.unesco.org/en/list/'],['three.js · wllama · llama.cpp · Qwen2.5','MIT · MIT · MIT · Apache-2.0','https://huggingface.co/Qwen/Qwen2.5-0.5B-Instruct-GGUF']].map(([a,b,u])=>`<div class="list-row"><div><strong>${esc(a)}</strong><p>${esc(b)}</p></div>${link(u,T('openOriginal'),'text-link end')}</div>`).join('')}<div class="notice">${esc(C('crew.fictional'))}</div></section><section class="panel" style="margin-top:22px"><h2>${esc(T('sources'))} · ${esc(T('photos'))}</h2>${photos.map(p=>`<div class="source-item"><img src="${p.path}" alt="${esc(L(p.title))}" loading="lazy"><div><h3>${safeText(p.title)}</h3><p>${esc(p.credit)}</p><p>${esc(p.license)}</p>${link(p.sourceUrl,T('openOriginal'))} · ${link(p.licenseUrl,'License')}</div></div>`).join('')}<div class="source-item"><div><h3>Natural Earth</h3><p>177 geographical features · Public domain · 249 ISO country/territory selector entries.</p>${link(mapCredit.sourceUrl,T('sources'))}</div></div></section><section class="panel" style="margin-top:22px"><h2>${esc(T('sources'))} · ${esc(T('videos'))}</h2>${[...mediaItems,maritimeMedia].map(v=>`<div class="list-row"><div><strong>${safeText(v.title)}</strong><p>${esc(v.channel)}</p></div>${link(v.sourceUrl,T('openOriginal'),'text-link end')}</div>`).join('')}<div class="notice">${esc(T('mediaNotice'))}</div></section>`}
function appearancePanel(){return `<section class="panel preference-panel"><h2>${esc(T('appearance'))}</h2><div class="form-grid"><div><label for="theme-setting">${esc(T('theme'))}</label><select id="theme-setting">${['system','light','dark'].map(v=>`<option value="${v}" ${v===theme?'selected':''}>${esc(T(v))}</option>`).join('')}</select></div><div><label for="density-setting">${esc(T('density'))}</label><select id="density-setting">${['comfortable','compact'].map(v=>`<option value="${v}" ${v===density?'selected':''}>${esc(T(v))}</option>`).join('')}</select></div></div><p class="hint" style="margin:15px 0 0">${esc(T('preferencesNotice'))}</p></section>`}
function supportsWebGL(){try{return !!document.createElement('canvas').getContext('webgl2')}catch{return false}}
const pages={home,planner:plannerPage,missions:missionLibrary,map:mapPage,training:trainingPage,crew:crewPage,academy:academyPage,aero:aeroPage,showcase:()=>embedPage(false),profile:profilePage,settings:settingsPage};
const tutor=createTutor({contextProvider:()=>coachContext||JSON.stringify({title:L(mission.title),description:L(mission.description),objectives:mission.objectives.map(L),checklist:mission.checklist.map(L)}),onStatus:s=>{const el=$('#model-status');if(el)el.textContent=`${T(s.state==='ready'?'AIReady':s.state==='loading'?'modelLoading':s.state==='generating'?'loading':'localModel')} ${s.state==='loading'?Math.round(s.progress*100)+'%':''} ${s.code||''}`;const p=$('#model-progress');if(p)p.value=s.progress}});
let chat=[];
function openCoach(){trainer?.pause();keys.clear();touchInputs.clear();input();mentorUI?.stop?.();const dialog=$('#coach-dialog');dialog.innerHTML=`<div class="dialog-head"><h2 id="coach-title">${esc(T('coach'))}</h2>${btn('close','close-coach','ghost','close')}</div><div class="notice">${esc(T('guideNotice'))}</div><div class="chat-log" id="chat-log"></div><form class="coach-form" id="coach-form"><input id="coach-question" maxlength="900" placeholder="${esc(T('coachPlaceholder'))}" aria-label="${esc(T('askCoach'))}"><button class="primary">${esc(T('send'))}</button>${btn('stop','stop-ai')}</form><details class="model-details"><summary>${esc(T('localModel'))} · ${MODEL_INFO.name}</summary><p>${esc(T('aiNotice'))}</p><div class="actions">${btn('downloadModel','load-default','soft')}${btn('unloadModel','unload-model')}</div><label for="model-file">${esc(T('chooseFile'))} · GGUF</label><input type="file" id="model-file" accept=".gguf"><label for="model-url" style="margin-top:10px">${esc(T('modelUrl'))}</label><div class="actions"><input id="model-url" type="url" placeholder="https://…/model.gguf" style="flex:1">${btn('loadModel','load-url')}</div><p id="model-status">${esc(T(tutor.status().state==='ready'?'AIReady':'localModel'))}</p><progress id="model-progress" max="1" value="${tutor.status().progress}"></progress><small>${MODEL_INFO.name} · 491 MB · Apache-2.0 · ${link(MODEL_INFO.source,T('sources'))}</small></details>`;renderChat();dialog.showModal();$('#coach-question').focus()}
function renderChat(){const el=$('#chat-log');if(el){el.innerHTML=chat.map(c=>`<div class="bubble ${c.role==='user'?'user':''}">${esc(c.text)}</div>`).join('');el.scrollTop=el.scrollHeight}}
async function askCoach(q){if(!q.trim())return;if(['loading','generating'].includes(tutor.status().state)){toast(T('loading'));return}chat.push({role:'user',text:q});$('#coach-question').value='';if(tutor.status().state!=='ready'){chat.push({role:'assistant',text:`${T('guide')} · ${T('guideNotice')}\n\n${coachContext?T('contextNotice')+'\n'+coachContext:L(mission.title)}\n${mission.objectives.map((o,i)=>`${i+1}. ${L(o)}`).join('\n')}\n\n${T('checklist')}\n${mission.checklist.map(L).join('\n')}`});renderChat();return}const row={role:'assistant',text:T('loading')};chat.push(row);renderChat();try{const answer=await tutor.ask(q,{language:lang,onToken:text=>{row.text=text;renderChat()}});row.text=answer.text;renderChat()}catch(e){row.text=`${T('error')}: ${e.code||'runtime'}`;renderChat()}}
function exportLast(data){try{sessionStorage.setItem('crew-last-result',JSON.stringify(data))}catch{}}
function download(data,name,type='application/json'){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportSession(){download(JSON.stringify({app:'Resilience Crew Lab',version:'3.0.0',created:new Date().toISOString(),locale:lang,missionId:mission.id,missionType:mission.type,place:mission.place?{id:mission.placeId,name:placeLabel(mission.place),lat:mission.place.lat,lon:mission.place.lon}:null,country:selectedCountry,trainingType:'fictional educational simulation',role,telemetry,result:simResult&&simResult.missionId===mission.id?simResult.result:null,digitalProgress:digitalStep,events:logs},null,2),'crew-training-report.json')}
async function doAction(action){switch(action){case 'open-sim':openSim();break;case 'fly-now':openSim(true);break;case 'close-sim':closeSim();break;case 'next-mission':nextMission();break;case 'menu':$('.sidebar').classList.toggle('open');$('.menu-overlay').classList.toggle('open');break;case 'crew':go('crew');break;case 'coach':coachContext=null;openCoach();break;case 'close-coach':$('#coach-dialog').close();break;case 'practice':go('training');break;case 'start':trainer?.start();break;case 'pause':trainer?.pause();break;case 'reset':checks.clear();digitalStep=0;logs=[];if(mission.domain==='digital')go('training');else trainer?.reset();$$('[data-check]').forEach(c=>c.checked=false);renderLogs();break;case 'assistance':assistance=!assistance;trainer?.setAssistance(assistance);$('[data-action="assistance"]')?.classList.toggle('soft',assistance);break;case 'inspect':trainer?.action('inspect');break;case 'return':trainer?.action('return');break;case 'confirm':if(checks.size<mission.checklist.length){toast(T('checklistNotice'));return}trainer?.action('confirm');addLog(T('confirm'),`${checks.size}/${mission.checklist.length}`);break;case 'photo':{if(trainer){const a=document.createElement('a');a.href=trainer.snapshot();a.download='crew-training.png';a.click()}break}case 'fullscreen':{const el=$('.trainer-area');if(document.fullscreenElement)await document.exitFullscreen();else if(el?.requestFullscreen)await el.requestFullscreen();else toast(T('unsupported'));break}case 'export':exportSession();break;case 'locate':if(!navigator.geolocation){toast(T('unsupported'));break}navigator.geolocation.getCurrentPosition(p=>{coords={lat:p.coords.latitude,lon:p.coords.longitude};if(page!=='map'||!$('#coordinate'))return;$('#coordinate').textContent=`${coords.lat.toFixed(5)}, ${coords.lon.toFixed(5)} ±${Math.round(p.coords.accuracy)}m`;$('#google-map').href=`https://www.google.com/maps/search/?api=1&query=${coords.lat},${coords.lon}`;drawMap()},e=>toast(`${T('permissionDenied')} (${e.code})`),{enableHighAccuracy:false,timeout:12000,maximumAge:60000});break;case 'create-room':await svc.createRoom('Crew Lab');renderRoom();break;case 'join-room':await svc.joinRoom($('#room-code-input').value.trim().toUpperCase());renderRoom();break;case 'leave-room':await svc.leaveRoom();renderRoom();break;case 'acknowledge':case 'crew-confirm':case 'crew-pause':await sendCrew({type:action,role});break;case 'load-video':loadVideo();break;case 'save-note':addLog(T('notes'),$('#learning-note').value);toast(T('record'));break;case 'guest':go('home');break;case 'send-code':if(svc.channelMode!=='cloud'){toast(T('cloudNotConfigured'));break}if(!$('#auth-email').checkValidity()||!$('#auth-email').value){toast(T('email'));break}await svc.sendOtp($('#auth-email').value.trim());toast(T('sendCode'));break;case 'verify-code':user=await svc.verifyOtp($('#auth-email').value.trim(),$('#auth-code').value.trim());go('profile');break;case 'save-profile':if(!user){toast(T('signIn'));break}await svc.saveProfile({displayName:$('#profile-name').value,phone:$('#profile-phone').value});toast(T('save'));break;case 'signout':await svc.signOut();user=null;go('profile');break;case 'load-default':await tutor.loadModel(await coachModelURL());toast(T('AIReady'));break;case 'load-url':{const value=$('#model-url').value.trim();if(!/^https:\/\//.test(value)&&!value.startsWith('./models/'))throw {code:'HTTPS_REQUIRED'};await tutor.loadModel(value);break}case 'unload-model':await tutor.unload();break;case 'stop-ai':tutor.cancel();break;}}
async function sendCrew(payload){if(room)await svc.sendEvent(payload);else{addLog(T('teamAction'),`${T(role)} · ${payload.type}${payload.text?': '+payload.text:''}`);toast(T('localSession'))}}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]'),act=e.target.closest('[data-action]'),m=e.target.closest('[data-mission]'),f=e.target.closest('[data-filter]'),c=e.target.closest('[data-country]'),r=e.target.closest('[data-role]'),v=e.target.closest('[data-video]'),em=e.target.closest('[data-embed]'),d=e.target.closest('[data-digital]');if(nav){e.preventDefault();go(nav.dataset.nav)}else if(act){e.preventDefault();doAction(act.dataset.action).catch(failure)}else if(m){mission=missions.find(x=>x.id===m.dataset.mission);checks.clear();digitalStep=0;telemetry=null;difficulty=mission.level;logs=[];pendingSim=mission.domain!=='digital';go('training')}else if(f){filter=f.dataset.filter;go('missions')}else if(c&&countries.some(x=>x.id===c.dataset.country)){selectedCountry=c.dataset.country;if(page==='home')go('map');else{const select=$('#country-select');select.value=selectedCountry;select.dispatchEvent(new Event('change',{bubbles:true}))}}else if(r){role=r.dataset.role;sendCrew({type:'role',role}).catch(failure);go('crew')}else if(v){selectedVideo=[...mediaItems,maritimeMedia].find(x=>x.id===v.dataset.video);go('academy')}else if(em){const urls={aero:'https://kuonanhong.github.io/AERO_Explorer/','aero-local':'aero/index.html',museum:'https://kuonanhong.github.io/HoloArtisan_PortraitMuseum/',holo:'https://kuonanhong.github.io/HoloArtisanDemo/'};activeEmbedded=em.dataset.embed;$('#embed-shell').innerHTML=`<iframe title="${esc(activeEmbedded)}" src="${urls[activeEmbedded]}" allow="fullscreen; geolocation" referrerpolicy="strict-origin-when-cross-origin" loading="lazy"></iframe>`}else if(d){digitalStep++;checks.add(Number(d.dataset.digital));addLog(T('confirm'),L(mission.deskSteps[digitalStep-1]));if(digitalStep===mission.deskSteps.length)toast(`${T('missionComplete')} · 100/100`);go('training')}});
document.addEventListener('change',e=>{const el=e.target;if(el.id==='theme-setting'){theme=el.value;try{localStorage.setItem('crew-theme',theme)}catch{}applyPreferences()}if(el.id==='density-setting'){density=el.value;try{localStorage.setItem('crew-density',density)}catch{}applyPreferences()}if(el.id==='locale'){lang=localeCode(el.value);try{localStorage.setItem('crew-language',lang)}catch{}Promise.all([loadLocaleExtras(lang),loadCrewText(lang)]).then(()=>go(page))}if(el.id==='domain-filter'){filter=el.value;$('#mission-cards').innerHTML=filteredCards()}if(el.id==='level-filter'){level=el.value;$('#mission-cards').innerHTML=filteredCards()}if(el.id==='region-filter'){region=el.value;$('#mission-cards').innerHTML=filteredCards()}if(el.id==='type-filter'){mtype=el.value;$('#mission-cards').innerHTML=filteredCards()}if(el.id==='country-select'){selectedCountry=el.value;coords=null;$('#country-name').textContent=cname(selectedCountry);$('#google-map').href=`https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(cname(selectedCountry))}`;$('#coordinate').textContent=T('noLiveData');drawMap()}if(el.id==='difficulty'){difficulty=el.value;trainer?.setDifficulty(difficulty)}if(el.id==='weather'){weather=el.value;trainer?.setWeather(weather)}if(el.id==='camera'){camera=el.value;trainer?.setCamera(camera)}if(el.dataset.check!==undefined){const n=Number(el.dataset.check);el.checked?checks.add(n):checks.delete(n)}if(el.id==='model-file'&&el.files[0])tutor.loadModel(el.files[0]).catch(failure);if(el.id==='local-video'&&el.files[0]){if(videoURL)URL.revokeObjectURL(videoURL);videoURL=URL.createObjectURL(el.files[0]);$('#video-screen').innerHTML=`<video src="${videoURL}" controls playsinline></video>`}});
document.addEventListener('input',e=>{if(e.target.id==='mission-search'){query=e.target.value;$('#mission-cards').innerHTML=filteredCards()}});
document.addEventListener('submit',e=>{if(e.target.id==='coach-form'){e.preventDefault();askCoach($('#coach-question').value).catch(failure)}if(e.target.id==='crew-message-form'){e.preventDefault();const input=$('#crew-message');if(input.value.trim())sendCrew({type:'message',role,text:input.value.trim()}).catch(failure);input.value=''}});
document.addEventListener('keydown',e=>{if(page!=='training'||simFrame||!trainer||$('#coach-dialog').open||(['INPUT','TEXTAREA','SELECT'].includes(e.target.tagName)||e.target.isContentEditable))return;const k=e.key.toLowerCase();if(['w','a','s','d','q','e','r','f','arrowup','arrowdown','arrowleft','arrowright',' '].includes(k)){e.preventDefault();if(k===' '){trainer?.pause();return}keys.add(k);input()}});
document.addEventListener('keyup',e=>{keys.delete(e.key.toLowerCase());input()});
document.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-pad]');if(!b||b.disabled)return;e.preventDefault();b.setPointerCapture(e.pointerId);b.classList.add('pressed');touchInputs.set(e.pointerId,{axis:b.dataset.pad,value:Number(b.dataset.value)});input()});
for(const ev of ['pointerup','pointercancel','lostpointercapture'])document.addEventListener(ev,e=>{touchInputs.delete(e.pointerId);e.target.closest('[data-pad]')?.classList.remove('pressed');input()});
window.addEventListener('blur',()=>{keys.clear();touchInputs.clear();input();trainer?.pause()});document.addEventListener('visibilitychange',()=>{if(document.hidden){keys.clear();touchInputs.clear();input();trainer?.pause()}});
svc.subscribe(e=>{if(e.type==='room'){if(room?.id!==e.room?.id){remoteState=null;members=[]}room=e.room;renderRoom();simPost({type:'room',code:room?.code||''})}if(e.type==='members'){members=e.members;renderRoom()}if(e.type==='state'){remoteState=e.state;renderRoom()}if(e.type==='event'){const p=e.event.payload;addLog(T('teamAction'),`${T(p.role||'member')} · ${p.text||p.type}`);if(p.type==='crew-pause'&&svc.isHost){trainer?.pause();simPost({type:'pause'})}}if(e.type==='auth'){user=e.user}if(e.type==='error')failure(e.error||{code:e.code})});
/* ======================= v3: Crew Lab missions at real places, realistic simulator overlay, coach bridge ======================= */
function dname(d){return d==='under'?C('crew.dom.under'):T(d)}
function placeLabel(p){if(!p)return '';return lang==='zh-Hant'?p.zh:lang==='zh-Hans'?(p.zhs||p.zh):(p.en||p.zh)}
function placeWhere(p){if(!p)return '';if(p.cc==='TW')return lang.startsWith('zh')?(p.region||cname('TW')):cname('TW');return /^[A-Z]{2}$/.test(p.cc||'')?cname(p.cc):''}
function deskArt(m){const [c,d]=CREW_ICONS[m.type]||['#456','M4 4h16v16H4z'],lv=m.level==='basic'?0:1,id=m.id.replace(/[^a-z0-9]/gi,'');return `<svg viewBox="0 0 400 170" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><defs><linearGradient id="g${id}" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="${c}"/><stop offset="1" stop-color="#11262b"/></linearGradient><pattern id="p${id}" width="${lv?24:16}" height="${lv?24:16}" patternUnits="userSpaceOnUse">${lv?'<path d="M0 0H24M0 0V24" stroke="#fff" stroke-opacity=".13"/>':'<circle cx="2" cy="2" r="1.3" fill="#fff" fill-opacity=".2"/>'}</pattern></defs><rect width="400" height="170" fill="url(#g${id})"/><rect width="400" height="170" fill="url(#p${id})"/><g transform="translate(${lv?226:44} 20) scale(5.4)" fill="none" stroke="#fff" stroke-width=".9" stroke-linecap="round" stroke-linejoin="round"><path d="${d}"/></g><g transform="translate(${lv?52:262} 64) scale(2.3)" fill="none" stroke="#fff" stroke-opacity=".38" stroke-width="1.2" stroke-linecap="round"><path d="${d}"/></g></svg>`}
function cardArt(m,cls=''){const col=crewColor(m.type);if(!m.place)return `<div class="crew-art desk ${cls}" style="--tc:${col}">${deskArt(m)}<span class="crew-badge">${crewIcon(m.type,26)}</span></div>`;const s=satTiles(m.place.lat+m.sat.oy,m.place.lon+m.sat.ox,m.sat.z);return `<div class="crew-art ${cls}" style="--tc:${col}"><div class="sat" style="left:calc(50% - ${Math.round(s.fx*256)}px);top:calc(50% - ${Math.round(s.fy*256)}px)">${s.tiles.map(u=>`<img src="${u}" alt="" loading="lazy" decoding="async" referrerpolicy="strict-origin-when-cross-origin" onerror="this.style.visibility='hidden'">`).join('')}</div><span class="crew-pin" aria-hidden="true"></span><span class="crew-badge">${crewIcon(m.type,26)}</span><span class="crew-credit">Esri · Maxar</span></div>`}
function simLauncher(){const r=simResult&&simResult.missionId===mission.id?simResult.result:null;return `<div class="sim-launch">${cardArt(mission,'big')}<div class="sim-launch-body"><p>${esc(C('crew.simIntro'))}</p>${r?`<p class="crew-score"><b>${esc(C('crew.total',{s:r.total}))}</b> · ${esc(C('crew.scoreLine',{c:r.done,t:r.count,s:r.safety,tm:r.time,i:r.inspect}))}</p>`:''}<div class="telemetry" aria-live="off"><span>${esc(T('progress'))}<strong id="tm-progress">–</strong></span><span>m/s<strong id="tm-speed">–</strong></span><span>m<strong id="tm-altitude">–</strong></span><span>BAT<strong id="tm-battery">–</strong></span><span>${esc(T('score'))}<strong id="tm-score">${r?r.total:'–'}</strong></span></div><div class="actions"><button class="primary btn-icon" data-action="open-sim">${icon('fly')}${esc(C('crew.open'))}</button><button class="soft btn-icon" data-action="next-mission">${esc(C('crew.nextMission'))}${icon('arrow')}</button></div></div></div>`}
function aeroPage(){return `${heading('practice','AERO')}<section class="hero"><div class="hero-copy"><div class="eyebrow">AERO · REAL WORLD</div><h1>${esc(C('crew.freeFlight'))}</h1><p>${esc(C('crew.simIntro'))}</p><div class="actions"><button class="primary btn-icon" data-action="fly-now">${icon('fly')}${esc(C('crew.flyNow'))}</button>${link('https://kuonanhong.github.io/AERO_Explorer/','AERO Explorer')}</div><small style="margin-top:18px">${esc(C('crew.imagery'))}</small></div><div class="hero-visual"><img src="assets/taiwan-coast.webp" alt="${esc(L(photos[0].title))}"></div></section><div class="notice">${esc(C('crew.fictional'))}</div>`}
function simURL(free){const q=`?lang=${encodeURIComponent(lang)}&role=${encodeURIComponent(role)}`;return free?`sim/index.html${q}#${DEFAULT_PLACE}/drone`:`sim/index.html${q}#crew/${encodeURIComponent(mission.id)}`}
function openSim(free=false){closeSim(true);if(!supportsWebGL()){toast(T('webglNotice'));return}const wrap=document.createElement('div');wrap.id='sim-overlay';wrap.setAttribute('role','dialog');wrap.setAttribute('aria-modal','true');const title=free?'AERO':L(mission.title);wrap.setAttribute('aria-label',title);wrap.innerHTML=`<iframe title="${esc(title)}" src="${simURL(free)}" allow="fullscreen; gamepad; autoplay; screen-wake-lock"></iframe>`;document.body.appendChild(wrap);document.body.classList.add('sim-open');simFrame=wrap.querySelector('iframe');simFrame.addEventListener('load',()=>{try{simFrame.contentWindow.focus()}catch{}});addLog(T('practice'),free?'AERO':mission.id)}
function closeSim(silent){const w=$('#sim-overlay');if(!w)return;w.remove();document.body.classList.remove('sim-open');simFrame=null;if(!silent&&page==='training')go('training')}
function simPost(msg){try{simFrame?.contentWindow?.postMessage({source:'rcl',...msg},location.origin)}catch{}}
function nextMission(){const i=missions.indexOf(mission);mission=missions[(i+1)%missions.length];checks.clear();digitalStep=0;telemetry=null;logs=[];difficulty=mission.level;pendingSim=mission.domain!=='digital';go('training')}
function registerExtras(kind,mod){const x=EXTRA[lang];if(!x)return;try{if(kind==='mentor'&&x.mentorLabels)mod.registerMentorLocale(lang,x.mentorLabels,x.mentorSteps,SPEECH[lang]);if(kind==='media'&&x.media)mod.mediaWorkspaceStrings[lang]={...mod.mediaWorkspaceStrings.en,...x.media};if(kind==='planner'&&x.planner){mod.plannerStrings[lang]={...mod.plannerStrings.en,...x.planner};if(!mod.plannerLocales.includes(lang))mod.plannerLocales.push(lang);if(x.plannerStory?.length)mod.SCENARIO_TEXT[lang]=x.plannerStory}}catch(e){console.warn('locale',kind,e)}}
/* the simulator asks the on-device coach (wllama + the site's GGUF model); nothing leaves the browser */
let coachLoading=null;
function coachStatus(){const s=tutor.status();return {state:s.state==='generating'?'ready':s.state,progress:s.progress||0,code:s.code||''}}
async function ensureCoach(){const st=tutor.status().state;if(st==='ready'||st==='generating')return;if(!coachLoading)coachLoading=(async()=>{try{await tutor.loadModel(await coachModelURL())}finally{coachLoading=null}})();return coachLoading}
async function coachLoadForSim(){const iv=setInterval(()=>simPost({type:'coach-status',...coachStatus()}),700);try{await ensureCoach()}catch(e){}finally{clearInterval(iv);simPost({type:'coach-status',...coachStatus()})}}
async function simAsk(d){const reply=(type,x={})=>simPost({type,id:d.id,...x}),st=tutor.status().state;if(st!=='ready'){reply('answer-error',{code:st==='loading'?'loading':'not-ready'});return}try{const r=await tutor.ask(String(d.q||''),{language:String(d.language||'English'),context:String(d.context||''),onToken:text=>reply('answer-progress',{text})});reply('answer',{text:r.text})}catch(e){reply('answer-error',{code:e.code||'coach'})}}
window.addEventListener('message',e=>{if(e.origin!==location.origin||e.data?.source!=='aero-crew'||!simFrame||e.source!==simFrame.contentWindow)return;const d=e.data;
 if(d.type==='ready'){simPost({type:'room',code:room?.code||''});simPost({type:'coach-status',...coachStatus()});if(d.missionId&&d.missionId!==mission.id){const m=missions.find(x=>x.id===d.missionId);if(m){mission=m;logs=[]}}addLog(T('practice'),`${d.missionId||'AERO'} · ${d.vehicle||''}`)}
 else if(d.type==='telemetry')updateTelemetry(d);
 else if(d.type==='event')addLog(T('record'),d.text||d.code);
 else if(d.type==='start')addLog(T('start'),d.missionId||'');
 else if(d.type==='checklist')addLog(T('confirm'),`${d.count||3}/3`);
 else if(d.type==='role'&&roles.some(r=>r.id===d.role)){role=d.role;try{localStorage.setItem('crew-role',role)}catch{}}
 else if(d.type==='complete'){simResult={missionId:d.missionId,result:d.result,at:Date.now()};addLog(T('missionComplete'),`${d.result.total}/100`);toast(`${T('missionComplete')} · ${d.result.total}/100`);exportLast({missionId:d.missionId,...d.result});if(room&&svc.isHost)svc.publishState({missionId:d.missionId,role,country:selectedCountry,telemetry:{...(telemetry||{}),score:d.result.total,complete:true},checkCount:3}).catch(failure)}
 else if(d.type==='report')addLog(T('notes'),String(d.record?.report||'').slice(0,160));
 else if(d.type==='close')closeSim();
 else if(d.type==='ask')simAsk(d);
 else if(d.type==='coach-load')coachLoadForSim();
 else if(d.type==='coach-query')simPost({type:'coach-status',...coachStatus()});
});
svc.getUser().then(u=>{user=u;if(u){const label=$('.account-label');if(label)label.textContent=T('profile');if(page==='profile')go('profile')}}).catch(()=>{});render();
